import sys
from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        # Filter numbers that are <= threshold
        # Numbers > threshold cannot form any edge because lcm(a, b) >= a and lcm(a, b) >= b
        large_nums_count = 0
        s = []

        for x in nums:
            if x <= threshold:
                s.append(x)
            else:
                large_nums_count += 1

        # If no numbers are <= threshold, all are isolated
        if not s:
            return large_nums_count

        # DSU initialization
        # We need to support nodes 1 to threshold.
        # Nodes in s are real nodes. Nodes not in s (but <= threshold) are virtual nodes.
        parent = list(range(threshold + 1))
        rank = [0] * (threshold + 1)

        def find(i):
            path = []
            while i != parent[i]:
                path.append(i)
                i = parent[i]
            for node in path:
                parent[node] = i
            return i

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                if rank[root_i] < rank[root_j]:
                    parent[root_i] = root_j
                elif rank[root_i] > rank[root_j]:
                    parent[root_j] = root_i
                else:
                    parent[root_j] = root_i
                    rank[root_i] += 1
                return True
            return False

        # For each number x in s, connect it to all its multiples M <= threshold
        # This effectively connects any two numbers that share a common multiple M <= threshold
        for x in s:
            # Iterate multiples: x, 2x, 3x, ... up to threshold
            # We start from x itself, union(x, x) is a no-op, but it's safe.
            for m in range(x, threshold + 1, x):
                union(x, m)

        # Count unique components among the real numbers in s
        roots = set()
        for x in s:
            roots.add(find(x))

        return len(roots) + large_nums_count

def main():
    input_data = sys.stdin.read().splitlines()
    # Filter out empty lines
    lines = [line.strip() for line in input_data if line.strip()]

    if not lines:
        return

    # Parse nums from the first line
    nums_str = lines[0]
    # Remove brackets and split by comma
    nums_str = nums_str.replace('[', '').replace(']', '')
    if nums_str:
        nums = list(map(int, nums_str.split(',')))
    else:
        nums = []

    # Parse threshold from the second line
    if len(lines) > 1:
        threshold = int(lines[1])
    else:
        threshold = 0

    sol = Solution()
    result = sol.countComponents(nums, threshold)
    print(result)

